INSERT INTO config.sales_competency_framework (id,version_no,status,display_name,dimensions,scoring_rules) SELECT id,version_no,status,display_name,dimensions,scoring_rules FROM jsonb_populate_record(NULL::config.sales_competency_framework, '{"id":"9419cdd3-d9ba-4a6a-8d99-0c0be46c5479","status":"active","dimensions":[{"code":"needs_discovery","name":"需求洞察","weight":0.18,"short_name":"需求","description":"识别显性需求、隐性动机、业务痛点与成功标准"},{"code":"stakeholder_navigation","name":"决策链经营","weight":0.16,"short_name":"决策链","description":"识别决策人、影响者、使用者及其立场并推进共识"},{"code":"solution_communication","name":"方案沟通","weight":0.18,"short_name":"方案","description":"将方案价值与客户场景、收益和异议有效连接"},{"code":"opportunity_advancement","name":"商机推进","weight":0.2,"short_name":"推进","description":"形成明确里程碑、时间表、责任人并持续推进"},{"code":"relationship_management","name":"客户关系","weight":0.14,"short_name":"关系","description":"建立信任、保持互动并拓展关键关系覆盖"},{"code":"followup_discipline","name":"跟进执行","weight":0.14,"short_name":"执行","description":"记录完整、行动清晰、反馈及时并闭环承诺"}],"version_no":1,"display_name":"企业销售六维能力模型","scoring_rules":{"score_range":[0,100],"evidence_required":true,"review_window_days":30,"minimum_visit_count":1}}'::jsonb) ON CONFLICT DO NOTHING;
